using System.Text.Json; using Amazon.Lambda.APIGatewayEvents; using OficinaMecanica.AuthLambda.Application;
namespace OficinaMecanica.AuthLambda.Function;
public sealed class Function(AutenticarClientePorDocumento useCase) { public async Task<APIGatewayHttpApiV2ProxyResponse> Handler(APIGatewayHttpApiV2ProxyRequest request) { string? documento; try { documento=JsonSerializer.Deserialize<Entrada>(request.Body ?? "{}")?.Documento; } catch(JsonException) { return Resposta(400,new { mensagem="Requisição inválida.",tipo="Validacao",erros=new[]{"Requisição inválida."} }); } var r=await useCase.ExecutarAsync(documento,default); return r.Tipo switch { ResultadoTipo.Sucesso=>Resposta(200,new { accessToken=r.Token,tokenType="Bearer",expiresIn=3600 }), ResultadoTipo.Invalido=>Resposta(400,new { mensagem="Requisição inválida.",tipo="Validacao",erros=new[]{"Requisição inválida."} }), ResultadoTipo.NaoAutorizado=>Resposta(401,new { mensagem="Documento não autorizado.",tipo="NaoAutorizado"}), _=>Resposta(503,new { mensagem="Serviço temporariamente indisponível.",tipo="ErroInterno"}) }; } private static APIGatewayHttpApiV2ProxyResponse Resposta(int s,object b)=>new(){StatusCode=s,Headers=new Dictionary<string,string>{{"Content-Type","application/json"}},Body=JsonSerializer.Serialize(b)}; private sealed record Entrada(string? Documento); }
